public class Main {
    public static void main(String[] args) throws Exception {
        String s = new FastReader().next();
        int minimum = 10;
        int[] counts = new int[10];
        for (int i = s.length() - 1; i >= 0; i--) {
            int value = s.charAt(i) - '0';
            if (value > minimum) counts[Math.min(value + 1, 9)]++;  // a smaller digit sits to its right: move it
            else { counts[value]++; minimum = value; }
        }
        StringBuilder sb = new StringBuilder();
        for (int d = 0; d < 10; d++) sb.append(String.valueOf((char) ('0' + d)).repeat(counts[d]));
        System.out.println(sb);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

